// Bundle server/chat/system-prompts/*.md into a TS module so serverless bundles need no file-system access.
// `--check` fails when the generated file is stale (used by tests/CI).
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const DIR = join(import.meta.dirname, '../../server/chat/system-prompts');
const OUT = join(import.meta.dirname, '../../server/chat/prompts.generated.ts');

export function splitLocales(md: string, file: string): { id: string; en: string } {
  const body = md.replace(/^<!--[\s\S]*?-->\s*/, '');
  const m = /^# id\s*\n([\s\S]*?)^# en\s*\n([\s\S]*)$/m.exec(body);
  if (!m) throw new Error(`${file}: expected "# id" and "# en" sections`);
  return { id: m[1]!.trim(), en: m[2]!.trim() };
}

export function render(): string {
  const files = readdirSync(DIR)
    .filter((f) => f.endsWith('.md'))
    .sort();
  const entries = files.map(
    (f) => [f.replace(/\.md$/, ''), splitLocales(readFileSync(join(DIR, f), 'utf8'), f)] as const,
  );
  return `// © 2026 Dea Saka Kurnia Putra. All rights reserved.\n// GENERATED by scripts/chat/bundle-prompts.ts from server/chat/system-prompts/*.md — do not edit by hand.\n\nexport const PROMPTS: Record<string, { id: string; en: string }> = ${JSON.stringify(Object.fromEntries(entries), null, 2)};\n`;
}

if (import.meta.main || process.argv[1]?.endsWith('bundle-prompts.ts')) {
  const txt = render();
  if (process.argv.includes('--check')) {
    if (readFileSync(OUT, 'utf8') !== txt) {
      console.error('prompts.generated.ts is stale — run npm run prompts:build');
      process.exit(1);
    }
  } else writeFileSync(OUT, txt);
}
